from classification import classify_name as _classify_name


def summarize(names):
    result = {}
    for name in names:
        category = _classify_name(name)
        result[category] = result.get(category, 0) + 1
    return result
"""Internal filename classification rules; not a public API."""


def classify_name(name):
    suffix = name.rsplit(".", 1)[-1] if "." in name else ""
    if suffix in ("txt", "md"):
        return "text"
    elif suffix in ("csv", "json"):
        return "data"
    else:
        return "other"

